 s:=t.shard(id)
 s.Lock()
 items,ok:=s.streams[id]
 if !ok{
  if err:=dbConn.SelectContext(ctx,&items,t.query+" LIMIT ?",id,timelinePageSize);err!=nil{s.Unlock();return nil,err}
  s.streams[id]=items
 }
 if limit>=0 && limit<=len(items) || len(items)<timelinePageSize {
  if limit>=0 && limit<len(items){items=items[:limit]}
  page:=append([]T{},items...);s.Unlock();return page,nil
 }
 s.Unlock()
 query:=t.query
 if limit>=0{query+=fmt.Sprintf(" LIMIT %d",limit)}
 var all []T
 if err:=dbConn.SelectContext(ctx,&all,query,id);err!=nil{return nil,err}
 return all,nil
}
