func updateZone(ctx context.Context, label string) error {
	base := os.Getenv("ZONE_CONTROL_URL")
	if base == "" {
		var cmd *exec.Cmd
		if label == "" {
			cmd = exec.CommandContext(ctx, "../pdns/init_zone.sh")
		} else {
