func consume(address string, template []byte) {
	for first := range changes {
		batch := []change{first}
	drain:
		for len(batch) < cap(changes) {
			select {
			case next := <-changes:
				batch = append(batch, next)
			default:
				break drain
			}
		}
		err := apply(batch, address, template)
		if err != nil {
			log.Print(err)
		}
		for _, change := range batch {
			change.done <- err
		}
	}
}

func update(w http.ResponseWriter, r *http.Request) {
	host, _, _ := net.SplitHostPort(r.RemoteAddr)
	key := os.Getenv("ZONE_CONTROL_TOKEN")
	if host != "10.99.0.13" || key == "" || subtle.ConstantTimeCompare([]byte(r.Header.Get("Authorization")), []byte("Bearer "+key)) != 1 {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	if r.Method != http.MethodPost {
		http.Error(w, "method", 405)
		return
	}
	if strings.HasPrefix(r.URL.Path, "/icons/") {
		iconUpdate(w, r)
		return
	}
	ch := change{done: make(chan error, 1)}
	switch r.URL.Path {
	case "/reset":
	case "/add":
		ch.label = r.URL.Query().Get("label")
		if !encodedLabel.MatchString(ch.label) {
			http.Error(w, "invalid DNS label", 400)
			return
		}
	default:
		http.NotFound(w, r)
		return
	}
	select {
	case changes <- ch:
	case <-r.Context().Done():
		return
	}
	select {
	case err := <-ch.done:
		if err != nil {
			http.Error(w, "zone update failed", 500)
			return
		}
	case <-r.Context().Done():
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

